from pathlib import Path
import json
import shutil
import sys

def strict_replace(source: str, old: str, new: str, name: str) -> str:
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f"[{name}] expected exactly 1 match, found {count}")
    return source.replace(old, new, 1)

def strict_remove(source: str, old: str, name: str) -> str:
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f"[{name}] expected exactly 1 match, found {count}")
    return source.replace(old, "", 1)

def main() -> None:
    if len(sys.argv) < 2:
        raise SystemExit("usage: python rewrite_env_dot_only_probe.py <path-to-env.py>")
    src = Path(sys.argv[1])
    text = src.read_text(encoding="utf-8")
    ops = []
    text = strict_replace(text, '_TRACE_LOG_PATH_ENV = "GITCG_IO_TRACE_PATH"\n_TRACE_LOG_DEFAULT = "gitcg_io_trace.jsonl"\n\n\ndef _trace_log_path() -> str:\n    configured = os.environ.get(_TRACE_LOG_PATH_ENV)\n    if configured and configured.strip():\n        return configured.strip()\n    return os.path.join(os.getcwd(), _TRACE_LOG_DEFAULT)\n\n\ndef _json_safe(value: Any):\n    if value is None or isinstance(value, (str, int, float, bool)):\n        return value\n    if isinstance(value, (list, tuple)):\n        return [_json_safe(item) for item in value]\n    if isinstance(value, dict):\n        return {str(key): _json_safe(val) for key, val in value.items()}\n    return repr(value)\n\n\ndef _append_trace_event(event: dict[str, Any]) -> None:\n    try:\n        payload = dict(event)\n        payload.setdefault("ts", time.time())\n        path = _trace_log_path()\n        with open(path, "a", encoding="utf-8") as handle:\n            handle.write(json.dumps(_json_safe(payload), ensure_ascii=False) + "\\n")\n    except Exception:\n        pass\n\n\ndef _state_brief(full_state: Any) -> dict[str, Any]:\n    return {\n        "phase": getattr(full_state, "phase", None),\n        "round_number": getattr(full_state, "round_number", None),\n        "current_turn": getattr(full_state, "current_turn", None),\n        "winner": getattr(full_state, "winner", None),\n    }\n', '_TRACE_LOG_PATH_ENV = "GITCG_IO_TRACE_PATH"\n_TRACE_LOG_DEFAULT = "gitcg_io_trace.jsonl"\n_PROBE_TOKEN = "116092.02"\n\n\ndef _trace_log_path() -> str:\n    configured = os.environ.get(_TRACE_LOG_PATH_ENV)\n    if configured and configured.strip():\n        return configured.strip()\n    return os.path.join(os.getcwd(), _TRACE_LOG_DEFAULT)\n\n\ndef _json_safe(value: Any):\n    if value is None or isinstance(value, (str, int, float, bool)):\n        return value\n    if isinstance(value, (list, tuple)):\n        return [_json_safe(item) for item in value]\n    if isinstance(value, dict):\n        return {str(key): _json_safe(val) for key, val in value.items()}\n    return repr(value)\n\n\ndef _contains_probe_token(value: Any) -> bool:\n    if value is None:\n        return False\n    if isinstance(value, str):\n        return _PROBE_TOKEN in value\n    if isinstance(value, (int, bool)):\n        return False\n    if isinstance(value, float):\n        return _PROBE_TOKEN in repr(value)\n    if isinstance(value, (list, tuple)):\n        return any(_contains_probe_token(item) for item in value)\n    if isinstance(value, dict):\n        return any(_contains_probe_token(key) or _contains_probe_token(val) for key, val in value.items())\n    return _PROBE_TOKEN in repr(value)\n\n\ndef _find_probe_snippets(text: str, token: str = _PROBE_TOKEN, *, radius: int = 140, limit: int = 2) -> list[str]:\n    snippets: list[str] = []\n    start = 0\n    while len(snippets) < limit:\n        index = text.find(token, start)\n        if index < 0:\n            break\n        left = max(0, index - radius)\n        right = min(len(text), index + len(token) + radius)\n        snippets.append(text[left:right].replace("\\n", " "))\n        start = index + len(token)\n    return snippets\n\n\ndef _state_probe_focus(raw_state_json: str | None) -> dict[str, Any]:\n    text = raw_state_json or ""\n    return {\n        "length": len(text),\n        "contains_probe_token": _PROBE_TOKEN in text,\n        "snippets": _find_probe_snippets(text),\n    }\n\n\ndef _append_trace_event(event: dict[str, Any]) -> None:\n    try:\n        payload = dict(event)\n        if not _contains_probe_token(payload):\n            return\n        payload.setdefault("ts", time.time())\n        path = _trace_log_path()\n        with open(path, "a", encoding="utf-8") as handle:\n            handle.write(json.dumps(_json_safe(payload), ensure_ascii=False) + "\\n")\n    except Exception:\n        pass\n\n\ndef _state_brief(full_state: Any) -> dict[str, Any]:\n    return {\n        "phase": getattr(full_state, "phase", None),\n        "round_number": getattr(full_state, "round_number", None),\n        "current_turn": getattr(full_state, "current_turn", None),\n        "winner": getattr(full_state, "winner", None),\n    }\n', "helpers_dot_only"); ops.append("helpers_dot_only")
    text = strict_replace(text, '        self._seed = seed if seed is not None else self._config.seed\n        initial_state_json = state_json if state_json is not None else self._initial_state_json\n        self._worker = Thread(\n', '        self._seed = seed if seed is not None else self._config.seed\n        initial_state_json = state_json if state_json is not None else self._initial_state_json\n        if initial_state_json is not None and _PROBE_TOKEN in initial_state_json:\n            _append_trace_event(\n                {\n                    "kind": "reset_state_json_dot",\n                    "matchup": self._matchup.key,\n                    "seed": self._seed,\n                    "focus": _state_probe_focus(initial_state_json),\n                }\n            )\n        self._worker = Thread(\n', "reset_dot_only_probe"); ops.append("reset_dot_only_probe")
    text = strict_replace(text, '                def on_io_error(self, error_msg: str):\n                    self.last_error = error_msg\n                    event = {\n                        "kind": "io_error",\n                        "matchup": env._matchup.key,\n                        "seed": env._seed,\n                        "player": self.who,\n                        "request_type": self.last_request_type,\n                        "request_summary": self.last_request_summary,\n                        "response_payload": self.last_response_payload,\n                        "error": error_msg,\n                        "recent_trace": list(self.trace_buffer),\n                    }\n                    self._push_trace(event)\n                    print(\n                        "[io-error-file] "\n                        f"path={_trace_log_path()} matchup={env._matchup.key} seed={env._seed} player={self.who}",\n                        flush=True,\n                    )\n', '                def on_io_error(self, error_msg: str):\n                    self.last_error = error_msg\n                    if _PROBE_TOKEN not in str(error_msg):\n                        return\n                    event = {\n                        "kind": "io_error",\n                        "matchup": env._matchup.key,\n                        "seed": env._seed,\n                        "player": self.who,\n                        "request_type": self.last_request_type,\n                        "request_summary": self.last_request_summary,\n                        "response_payload": self.last_response_payload,\n                        "error": error_msg,\n                        "recent_trace": list(self.trace_buffer),\n                    }\n                    self._push_trace(event)\n', "io_error_dot_only"); ops.append("io_error_dot_only")
    text = strict_remove(text, '                    if request_type == DecisionType.SELECT_CARD:\n                        raw_candidates = list(getattr(request, "candidate_definition_ids", ()))\n                        if any(\n                            (\n                                isinstance(value, float) and not value.is_integer()\n                            ) or (\n                                not isinstance(value, (int, bool, float))\n                            )\n                            for value in raw_candidates\n                        ):\n                            print(\n                                "[select-card-trace] "\n                                f"stage=env.request matchup={env._matchup.key} seed={env._seed} player={self.who} "\n                                f"step={step_index_ref[\'value\']} candidates={[repr(v) + \':\' + type(v).__name__ for v in raw_candidates]}",\n                                flush=True,\n                            )\n', "remove_select_card_trace_stdout"); ops.append("remove_select_card_trace_stdout")
    text = strict_replace(text, '                    _append_trace_event(\n                        {\n                            "kind": "terminal_guard",\n                            "matchup": self._matchup.key,\n                            "seed": self._seed,\n                            "reason": invalid_terminal_reason,\n                            "status": status_name,\n                            "raw_winner": raw_winner,\n                            "sanitized_winner": sanitized_winner,\n                            "error": error_message,\n                        }\n                    )\n', '                    _append_trace_event(\n                        {\n                            "kind": "terminal_guard",\n                            "matchup": self._matchup.key,\n                            "seed": self._seed,\n                            "reason": invalid_terminal_reason,\n                            "status": status_name,\n                            "raw_winner": raw_winner,\n                            "sanitized_winner": sanitized_winner,\n                            "error": error_message,\n                            "player0_io_error": player0.last_error,\n                            "player1_io_error": player1.last_error,\n                            "focus": _state_probe_focus(raw_state_json),\n                        }\n                    )\n', "terminal_guard_focus"); ops.append("terminal_guard_focus")
    text = strict_replace(text, '                    full_state_json = raw_state_json if env._config.record_full_state_json else None\n                    visible_snapshot = None\n', '                    full_state_json = raw_state_json if env._config.record_full_state_json else None\n                    if _PROBE_TOKEN in raw_state_json:\n                        _append_trace_event(\n                            {\n                                "kind": "request_state_dot",\n                                "matchup": env._matchup.key,\n                                "seed": env._seed,\n                                "player": self.who,\n                                "step_index": step_index_ref["value"],\n                                "request_type": request_type.name,\n                                "request_summary": self.last_request_summary,\n                                "focus": _state_probe_focus(raw_state_json),\n                            }\n                        )\n                    visible_snapshot = None\n', "request_state_dot_probe"); ops.append("request_state_dot_probe")

    required_present = ['_PROBE_TOKEN = "116092.02"', 'def _contains_probe_token(value: Any) -> bool:', 'def _state_probe_focus(raw_state_json: str | None) -> dict[str, Any]:', '"kind": "reset_state_json_dot"', 'if _PROBE_TOKEN not in str(error_msg):', '"kind": "request_state_dot"', '"player0_io_error": player0.last_error,', '"focus": _state_probe_focus(raw_state_json),']
    required_absent = ['[io-error-file]', '[select-card-trace]']
    missing = [m for m in required_present if m not in text]
    leftovers = [m for m in required_absent if m in text]

    backup = src.with_suffix(src.suffix + ".bak")
    shutil.copyfile(src, backup)
    src.write_text(text, encoding="utf-8")

    preview = src.with_name(src.stem + ".dot_only.py")
    preview.write_text(text, encoding="utf-8")

    report = {
        "source_file": str(src),
        "backup_file": str(backup),
        "preview_file": str(preview),
        "operations_applied": ops,
        "missing_required_new_markers": missing,
        "leftover_old_markers": leftovers,
        "success": not missing and not leftovers,
    }
    report_path = src.with_name(src.stem + ".dot_only_report.txt")
    report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    print(report_path)
    if missing or leftovers:
        raise SystemExit("rewrite finished but verification failed; inspect report")

if __name__ == "__main__":
    main()
